param([int]$Port=9491)
$ErrorActionPreference='Stop';$edge='C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe';$profile=Join-Path $env:TEMP "curdun-p15-phase3-$Port";$proc=Start-Process $edge -ArgumentList @('--headless','--disable-gpu','--disable-extensions','--no-first-run','--remote-allow-origins=*',"--remote-debugging-port=$Port","--user-data-dir=$profile",'http://localhost:8000/app.html') -WindowStyle Hidden -PassThru;$ws=$null
try{$page=$null;for($i=0;$i-lt60-and!$page;$i++){Start-Sleep -Milliseconds 200;try{foreach($c in (Invoke-RestMethod "http://localhost:$Port/json/list")){if($c.type-eq'page'-and$c.url-like'http://localhost:8000/*'){$page=$c;break}}}catch{}};if(!$page){throw'No page'};$ws=[Net.WebSockets.ClientWebSocket]::new();$ws.ConnectAsync([Uri]$page.webSocketDebuggerUrl,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null
$js=@'
(async()=>{const pause=ms=>new Promise(r=>setTimeout(r,ms));const wait=async(fn,l)=>{for(let i=0;i<180;i++){const v=fn();if(v)return v;await pause(100)}throw Error('Timeout '+l)};const fill=(e,v)=>{if(!e)throw Error('Missing input');e.value=String(v);e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}))};const pin=async(id,digits)=>{await wait(()=>document.querySelector(`[data-login-id="${id}"]`),'staff '+id);document.querySelector(`[data-login-id="${id}"]`).click();await pause(220);for(const d of digits){[...document.querySelectorAll('[data-key]')].find(b=>b.dataset.key===d).click();await pause(140)}await wait(()=>S.posActiveUser?.id===id,'PIN '+id)};await wait(()=>typeof posBootstrap==='function','scripts');S.view='pos';S.posActiveUser=null;S.posLoginMode='staff';render();await pause(500);await pin(3,'1234');await posBootstrap();const cold=await posApiFetch('/pos/sessions/32/summary');if(Number(S.posSession?.id)!==32||S.posSession.state!=='OPENED')throw Error('Cold reload lost session 32');if(Number(cold.expected_cash)!==258.93||Number(cold.orders)!==9)throw Error('Cold reload totals differ');if((S.posSessions||[]).some(s=>Number(s.id)===33))throw Error('Session 33 exists');const products=POS_PRODUCTS.filter(p=>[1,2,3].includes(Number(p.id))).map(p=>({id:p.id,name:p.name,stock:Number(p.stock)}));const customers=POS_CUSTOMERS.filter(c=>[1,3].includes(Number(c.id))).map(c=>({id:c.id,name:c.name,balance:Number(c.balance),points:Number(c.loyaltyPoints)}));
// Open the live Session Report through the rendered Reporting menu.
S.posView='backoffice';S.posBackofficeTab='dashboard';render();const reportingMenu=await wait(()=>document.querySelector('[data-nav-menu="reporting"]'),'Reporting menu');await pause(250);reportingMenu.click();const reportItem=await wait(()=>document.querySelector('[data-bo-tab="reports-session"]'),'Session Report item');await pause(250);reportItem.click();await wait(()=>document.querySelector('#report-session-select'),'live report');await pause(500);const liveText=document.querySelector('.pharm-content').textContent.replace(/\s+/g,' ').trim();const liveCompact=liveText.replace(/\s/g,'');for(const token of ['Session #32','OPEN','Net Sales $159.34','Gross Sales $161.23','Refunds $1.89','Cash','$138.93','EVC Plus','$11.62','ZAAD','$5.95','Deyn','$2.84','Customer-account collections $15.00','Expected Cash $258.93','Fartun Ali','Mohamed Farah'])if(!liveCompact.includes(token.replace(/\s/g,'')))throw Error('Live report missing '+token+' :: '+liveText.slice(0,1600));if((cold.orders_list||[]).map(o=>Number(o.id)).sort((a,b)=>a-b).join(',')!=='219,220,221,222,223,224,225,226,227')throw Error('Order boundary leak');const refund=cold.orders_list.find(o=>Number(o.id)===227);if(Number(refund?.refunded_order_id)!==220)throw Error('Refund link missing');
// Visible lock and Khadija ADVANCED PIN, then visible Closing Control.
document.querySelector('#btn-topnav-user').click();const lockButton=await wait(()=>document.querySelector('#btn-bo-lock'),'lock control');await pause(250);lockButton.click();await wait(()=>!S.posActiveUser,'locked for close');await pin(6,'3456');if(Number(S.posSession?.id)!==32)throw Error('Session changed on Khadija PIN');S.posView='backoffice';S.posBackofficeTab='sessions';render();const closeButton=await wait(()=>document.querySelector('#btn-session-close'),'close control');await pause(350);closeButton.click();await wait(()=>document.querySelector('#rc-close-counted'),'Closing Control');await pause(350);const closingText=document.querySelector('.crud-modal').textContent.replace(/\s+/g,' ').trim();if(!closingText.replace(/\s/g,'').includes('Expectedcash$258.93'))throw Error('Closing expected cash differs');fill(document.querySelector('#rc-close-counted'),'258.93');await pause(400);fill(document.querySelector('#rc-close-note'),'P15 full-day reconciliation');await pause(250);const varianceText=document.querySelector('.crud-modal').textContent.replace(/\s+/g,' ').trim();if(!varianceText.includes('Perfect match'))throw Error('Closing difference is not zero');document.querySelector('#rc-close-submit').click();await wait(()=>S.posRegisterModal?.mode==='closed-summary','register close');const closeResult=JSON.parse(JSON.stringify(S.posRegisterModal.result));await posBootstrap();if(S.posSession)throw Error('Current session remains after close');const historical=await posApiFetch('/pos/sessions/32/summary');if(historical.session.state!=='CLOSED'||Number(historical.cash_reconciliation.counted_cash)!==258.93||Number(historical.cash_reconciliation.difference)!==0)throw Error('Historical close mismatch');return{cold:{session:cold.session.id,state:cold.session.state,opening:Number(cold.session.opening_cash),expected:Number(cold.expected_cash),orders:Number(cold.orders),products,customers},live:{sales:cold.sales,payments:cold.payment_methods,cash:cold.cash_reconciliation,customer_account:cold.customer_account,employees:cold.employees,order_ids:cold.orders_list.map(o=>o.id),visible:liveText},khadija:{id:S.posActiveUser?.id,name:S.posActiveUser?.name,closingText,varianceText},closeResult,historical};})()
'@;$m=@{id=1;method='Runtime.evaluate';params=@{expression=$js;awaitPromise=$true;returnByValue=$true}}|ConvertTo-Json -Depth 8 -Compress;$bytes=[Text.Encoding]::UTF8.GetBytes($m);$ws.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null;while(1){$buf=New-Object byte[] 1048576;$x=$ws.ReceiveAsync([ArraySegment[byte]]::new($buf),[Threading.CancellationToken]::None).GetAwaiter().GetResult();$r=([Text.Encoding]::UTF8.GetString($buf,0,$x.Count)|ConvertFrom-Json);if($r.id-eq1){if($r.result.exceptionDetails){throw($r.result.exceptionDetails|ConvertTo-Json -Depth 12)};$r.result.result.value|ConvertTo-Json -Depth 40;break}}}finally{if($ws){$ws.Dispose()};if($proc-and!$proc.HasExited){Stop-Process $proc.Id -Force}}
